const getBestUrl = (article) => {
  return (
    article.html_url ||
    article.url ||
    article.link ||
    article.status_link ||
    article.twitter_url ||
    article.source_url ||
    null
  );
};

const getLinkLabel = (url) => {
  if (!url) return "Read More";

  if (url.includes("github.com")) return "View GitHub Repo";
  if (url.includes("/releases")) return "View Release Notes";
  if (url.includes("youtube.com")) return "Watch Demo";
  if (url.includes("docs.")) return "Read Documentation";
  if (url.includes("blog")) return "Read Engineering Breakdown";
  if (url.includes("twitter.com") || url.includes("x.com")) return "View Discussion";
  if (url.includes("vercel.com")) return "Read Product Update";
  if (url.includes("cloudflare.com")) return "Read Technical Breakdown";

  return "Read Full Breakdown";
};

// 1. EXTRACT ALL ARTICLES
let flatData = [];
const items = $input.all();

items.forEach(item => {
  const data = item.json;

  if (data.hits && Array.isArray(data.hits)) {
    flatData.push(...data.hits);
  } 
  else if (data.news_results && Array.isArray(data.news_results)) {
    flatData.push(...data.news_results);
  } 
  else if (data.tweets && Array.isArray(data.tweets)) {
    flatData.push(...data.tweets);
  }
  else if (data.items && Array.isArray(data.items)) {
    flatData.push(...data.items);
  }
  else if (Array.isArray(data)) {
    flatData.push(...data);
  }
  else {
    flatData.push(data);
  }
});

// 2. UNIQUE LIST
const uniqueList = Array.from(
  new Map(
    flatData.map(item => [
      item.html_url ||
      item.url ||
      item.link ||
      item.twitter_url ||
      item.status_link,
      item
    ])
  ).values()
);

// 3. GENERATE PROMPTS + FIXED URL LOGIC
return uniqueList
  .map(article => {

    const title =
      article.title ||
      article.name ||
      article.text ||
      article.story_title ||
      "Untitled";

    const snippet =
      article.snippet ||
      article.description ||
      article.body ||
      article.text ||
      article.story_text ||
      article.contentSnippet ||
      "No snippet available";

    if (!title || title.length < 20) return null;

    const url = getBestUrl(article);

    if (!url || url.includes("search") || url.includes("google.com")) {
      return null;
    }

    const now = Date.now();
    const articleDate = new Date(
      article.date ||
      article.publishedAt ||
      article.created_at ||
      article.pubDate ||
      now
    ).getTime();

    const ageHours = (now - articleDate) / (1000 * 60 * 60);

    let freshnessBoost = 0;
    if (ageHours < 24) freshnessBoost = 10;
    else if (ageHours < 72) freshnessBoost = 5;

    const ollamaPrompt = `
You are a senior AI developer newsletter curator.

Evaluate this content for:
- Real-world developer usage
- Productivity improvement
- Emerging tools or trends
- Signal vs noise

Give HIGH scores if:
- Copilot / Claude / Cursor workflows
- Automation or dev acceleration
- Real developer impact
- Framework releases
- GitHub launches
- Engineering blogs
- Technical implementation details
- Performance improvements
- Architecture changes

Give LOW scores if:
- Generic blogs
- Marketing fluff
- Opinion-only content
- Startup motivational posts
- Generic AI listicles

Reject content that is:
- motivational
- opinion-only
- not showing real implementation, workflow, or technical insight

TITLE: ${title}
SNIPPET: ${snippet}

Respond ONLY with a number from 0 to 100.
`;

    return {
      json: {
        title: title,
        url: url,

        linkLabel: getLinkLabel(url),

        source:
          article.source?.name ||
          article.source ||
          article.user?.name ||
          article.author ||
          "Industry Source",

        prompt: ollamaPrompt,

        freshnessBoost: freshnessBoost,

        date:
          article.date ||
          article.publishedAt ||
          article.created_at ||
          article.pubDate ||
          null,

        domain: (() => {
          try {
            return new URL(url).hostname.replace("www.", "");
          } catch {
            return null;
          }
        })(),

        sourceType: (() => {
          if (url.includes("github.com")) return "github";
          if (url.includes("react.dev")) return "framework_release";
          if (url.includes("nextjs.org")) return "framework_release";
          if (url.includes("tailwindcss.com")) return "framework_release";
          if (url.includes("vite.dev")) return "framework_release";
          if (url.includes("cloudflare.com")) return "engineering_blog";
          if (url.includes("vercel.com")) return "engineering_blog";
          if (url.includes("builder.io")) return "engineering_blog";
          if (url.includes("twitter.com") || url.includes("x.com")) return "social";
          return "general";
        })(),

        category: (() => {
          const text = `${title} ${snippet}`.toLowerCase();

          if (
            text.includes("ai") ||
            text.includes("agent") ||
            text.includes("llm") ||
            text.includes("copilot") ||
            text.includes("claude") ||
            text.includes("cursor")
          ) {
            return "ai_tooling";
          }

          if (
            text.includes("security") ||
            text.includes("cve") ||
            text.includes("vulnerability") ||
            text.includes("exploit")
          ) {
            return "security";
          }

          if (
            text.includes("react") ||
            text.includes("next.js") ||
            text.includes("nextjs") ||
            text.includes("vite") ||
            text.includes("tailwind") ||
            text.includes("bun") ||
            text.includes("supabase")
          ) {
            return "framework_release";
          }

          if (
            text.includes("performance") ||
            text.includes("cache") ||
            text.includes("compiler") ||
            text.includes("rendering") ||
            text.includes("optimization")
          ) {
            return "performance";
          }

          if (
            text.includes("database") ||
            text.includes("postgres") ||
            text.includes("supabase")
          ) {
            return "database";
          }

          return "general";
        })(),

        tags: (() => {
          const tags = [];
          const text = `${title} ${snippet}`.toLowerCase();

          if (text.includes("ai")) tags.push("ai");
          if (text.includes("agent")) tags.push("agent");
          if (text.includes("llm")) tags.push("llm");
          if (text.includes("copilot")) tags.push("copilot");
          if (text.includes("claude")) tags.push("claude");
          if (text.includes("cursor")) tags.push("cursor");
          if (text.includes("react")) tags.push("react");
          if (text.includes("next.js") || text.includes("nextjs")) tags.push("nextjs");
          if (text.includes("vite")) tags.push("vite");
          if (text.includes("tailwind")) tags.push("tailwind");
          if (text.includes("bun")) tags.push("bun");
          if (text.includes("supabase")) tags.push("supabase");
          if (text.includes("security")) tags.push("security");
          if (text.includes("performance")) tags.push("performance");
          if (text.includes("compiler")) tags.push("compiler");
          if (text.includes("cache")) tags.push("cache");
          if (text.includes("database")) tags.push("database");
          if (text.includes("postgres")) tags.push("postgres");

          return [...new Set(tags)];
        })()
      }
    };
  })
  .filter(Boolean);

const items = $input.all();

// 👇 this must match EXACT node name
const allOriginalArticles = $("Code in JavaScript").all();

return items.map((item, index) => {
  // 1. Extract score safely
  const ollamaResponse = item.json.response || "0";

  const scoreMatch = ollamaResponse.match(/\b([0-9]{1,3})\b/);

  let numericScore = scoreMatch ? parseInt(scoreMatch[1], 10) : 0;

  if (numericScore > 100) numericScore = 100;
  if (numericScore < 0) numericScore = 0;

  // 2. Get original article
  const originalArticle = allOriginalArticles[index].json;

  // 🔥 TWITTER PENALTY
  let penalty = 0;
  if (
    originalArticle.url &&
    (
      originalArticle.url.includes("twitter.com") ||
      originalArticle.url.includes("x.com")
    )
  ) {
    penalty = 10;
  }

  // 🔥 FINAL SCORE
  const finalScore =
    numericScore +
    (originalArticle.freshnessBoost || 0) -
    penalty;

  return {
    json: {
      title: originalArticle.title,
      url: originalArticle.url,
      linkLabel: originalArticle.linkLabel,
      source: originalArticle.source || "Industry Intelligence",

      // ✅ FINAL SCORE
      score: finalScore,

      // 🧠 DEBUG
      baseScore: numericScore,
      freshnessBoost: originalArticle.freshnessBoost || 0,
      penaltyApplied: penalty,

      // 🔥 SOURCE METADATA
      domain: originalArticle.domain || null,
      sourceType: originalArticle.sourceType || "general",
      category: originalArticle.category || null,

      // DB safe date
      date: originalArticle.date
        ? new Date(originalArticle.date).toISOString()
        : new Date().toISOString()
    }
  };
});

const now = Date.now();

return items
  .map(item => {
    const article = item.json;

    const title = article.title || "";
    const snippet = article.snippet || article.summary || "";
    const url = article.url || "";

    const lowerTitle = title.toLowerCase();
    const lowerSnippet = snippet.toLowerCase();
    const combinedText = `${lowerTitle} ${lowerSnippet}`;

    const date = article.date ? new Date(article.date).getTime() : now;
    const ageDays = (now - date) / (1000 * 60 * 60 * 24);

    // keep only articles from the last 7 days
    if (ageDays > 7) return null;

    // remove generic docs/tutorial content
    const weakKeywords = [
      "how to",
      "getting started",
      "introduction",
      "learn",
      "guide",
      "styling",
      "building apis",
      "introducing",
      "create next app",
      "recap",
      "conference",
      "conf",
      "rc",
      "release candidate"
    ];

    if (weakKeywords.some(keyword => combinedText.includes(keyword))) {
      return null;
    }

    // remove patch release spam
    const patchReleaseRegex = /^\d+\.\d+\.\d+/;
    if (patchReleaseRegex.test(lowerTitle)) {
      return null;
    }

    // remove duplicate security patch release titles
    if (
      lowerTitle.includes("security advisory") ||
      lowerTitle.includes("cve-") ||
      lowerTitle.includes("dos mitigations")
    ) {
      return null;
    }

    // keep only stronger keywords
    const strongKeywords = [
      "compiler",
      "turbopack",
      "agent",
      "ai",
      "performance",
      "cache",
      "server component",
      "rendering",
      "edge",
      "adapter",
      "view transitions",
      "migration",
      "sunsetting",
      "architecture",
      "workflow",
      "automation",
      "productivity",
      "llm",
      "inference",
      "fine-tuning"
    ];

    const hasStrongKeyword = strongKeywords.some(keyword =>
      combinedText.includes(keyword)
    );

    // if article has no strong signal words, remove it
    if (!hasStrongKeyword) {
      return null;
    }

    // auto category detection
    const category = (() => {
      if (
        combinedText.includes("ai") ||
        combinedText.includes("agent") ||
        combinedText.includes("llm") ||
        combinedText.includes("copilot") ||
        combinedText.includes("claude") ||
        combinedText.includes("cursor")
      ) {
        return "ai_tooling";
      }

      if (
        combinedText.includes("security") ||
        combinedText.includes("cve") ||
        combinedText.includes("vulnerability") ||
        combinedText.includes("exploit")
      ) {
        return "security";
      }

      if (
        combinedText.includes("react") ||
        combinedText.includes("next.js") ||
        combinedText.includes("nextjs") ||
        combinedText.includes("vite") ||
        combinedText.includes("tailwind")
      ) {
        return "framework_release";
      }

      if (
        combinedText.includes("performance") ||
        combinedText.includes("cache") ||
        combinedText.includes("compiler") ||
        combinedText.includes("rendering") ||
        combinedText.includes("optimization")
      ) {
        return "performance";
      }

      if (
        combinedText.includes("database") ||
        combinedText.includes("postgres") ||
        combinedText.includes("supabase")
      ) {
        return "database";
      }

      return "general";
    })();

    // auto tags generation
    const tags = [];

    if (combinedText.includes("ai")) tags.push("ai");
    if (combinedText.includes("agent")) tags.push("agent");
    if (combinedText.includes("llm")) tags.push("llm");
    if (combinedText.includes("react")) tags.push("react");
    if (combinedText.includes("next.js") || combinedText.includes("nextjs")) tags.push("nextjs");
    if (combinedText.includes("vite")) tags.push("vite");
    if (combinedText.includes("tailwind")) tags.push("tailwind");
    if (combinedText.includes("security")) tags.push("security");
    if (combinedText.includes("performance")) tags.push("performance");
    if (combinedText.includes("compiler")) tags.push("compiler");
    if (combinedText.includes("turbopack")) tags.push("turbopack");
    if (combinedText.includes("server component")) tags.push("server-components");
    if (combinedText.includes("cache")) tags.push("cache");
    if (combinedText.includes("database")) tags.push("database");
    if (combinedText.includes("postgres")) tags.push("postgres");
    if (combinedText.includes("supabase")) tags.push("supabase");

    return {
      json: {
        ...article,
        category,
        tags
      }
    };
  })
  .filter(Boolean);
